/*
 * prog38_continued_fraction – reconstructed from the supplied binary.
 *
 * Behaviour (exactly matches the original program):
 *
 *   1. If fewer than two command‑line arguments are supplied:
 *          prints "NO_INPUT" (followed by a newline) and exits.
 *
 *   2. If either argument cannot be parsed as a signed decimal integer:
 *          prints "BAD_INPUT" (newline) and exits.
 *
 *   3. If the denominator (second argument) is zero:
 *          prints "[]" (newline) and exits.
 *
 *   4. If the absolute value of the denominator is larger than 100 000:
 *          prints "OUT_OF_RANGE" (newline) and exits.
 *
 *   5. The program computes the continued‑fraction representation of the
 *      rational number numerator/denominator using the Euclidean algorithm.
 *
 *   6. If more than 199 partial quotients are required, it prints
 *          "ERROR" (newline) and exits.
 *
 *   7. Otherwise it prints the continued fraction in the form
 *
 *          a0; a1, a2, a3, ...
 *
 *      (no trailing newline, exactly as the original binary does).
 *
 *   8. Negative numbers are handled by normalising the denominator to be
 *      positive and keeping the sign on the first term.
 *
 * The implementation follows the same logical steps as the decompiled
 * state‑machine, but expressed in clear, portable C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

#define MAX_TERMS 200          /* the original program aborts after 199 terms */
#define DENOM_LIMIT 100000    /* limit that triggers OUT_OF_RANGE */

static int parse_long(const char *s, long long *out)
{
    char *endptr;
    errno = 0;
    long long v = strtoll(s, &endptr, 10);
    if (errno != 0)               return 0;   /* overflow / underflow */
    if (*endptr != '\0')          return 0;   /* non‑numeric characters */
    *out = v;
    return 1;
}

/* floor division that always yields a non‑negative remainder,
   matching the behaviour of the original program. */
static long long floor_div(long long a, long long b, long long *rem)
{
    long long q = a / b;
    long long r = a % b;
    if (r < 0) {
        if (b > 0) {
            q -= 1;
            r += b;
        } else {
            q += 1;
            r -= b;
        }
    }
    if (rem) *rem = r;
    return q;
}

int main(int argc, char **argv)
{
    /* ---------- 1. argument count ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- 2. parse arguments ---------- */
    long long num, den;
    if (!parse_long(argv[1], &num) || !parse_long(argv[2], &den)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- 3. denominator zero ---------- */
    if (den == 0) {
        puts("[]");
        return 0;
    }

    /* ---------- 4. denominator magnitude limit ---------- */
    long long abs_den = den < 0 ? -den : den;
    if (abs_den > DENOM_LIMIT) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- 5. normalise sign (denominator positive) ---------- */
    if (den < 0) {
        den = -den;
        num = -num;
    }

    /* ---------- 6. Euclidean algorithm – collect quotients ---------- */
    long long quotients[MAX_TERMS];
    int qcnt = 0;

    long long a = num, b = den;
    while (b != 0) {
        long long r;
        long long q = floor_div(a, b, &r);

        if (qcnt >= MAX_TERMS) {          /* more than 199 terms */
            puts("ERROR");
            return 0;
        }
        quotients[qcnt++] = q;

        a = b;
        b = r;
    }

    /* ---------- 7. output the continued fraction ---------- */
    if (qcnt == 0) {               /* should never happen, but be safe */
        puts("[]");
        return 0;
    }

    printf("%lld", quotients[0]);          /* first term, no newline */
    if (qcnt > 1) {
        printf("; ");
        for (int i = 1; i < qcnt; ++i) {
            if (i > 1) printf(", ");
            printf("%lld", quotients[i]);
        }
    }
    /* No trailing newline – matches the original binary's behaviour */
    return 0;
}
